import com.leafreader.app.Core;import java.util.*;
public class CoreTest {static int count=0;static void check(boolean value,String name){if(!value)throw new AssertionError(name);System.out.println("PASS: "+name);count++;}public static void main(String[] args){List<Core.Unit> units=new ArrayList<>();for(int i=0;i<40;i++)units.add(new Core.Unit("paragraph "+i,"test",false));List<Core.Page> pages=Core.paginate(units,u->50,100);check(pages.size()==20,"pagination covers every unit");int total=0;for(Core.Page p:pages)total+=p.end-p.start;check(total==units.size(),"no dropped or duplicated units");check(Core.window(pages,3).equals(Arrays.asList(6,7,8,9,10,11,12,13)),"exactly current page plus three pages");check(Core.window(pages,19).equals(Arrays.asList(38,39)),"last page clamps to end");Set<Integer> cache=new HashSet<>(Arrays.asList(0,1,2,3));check(Core.missing(Arrays.asList(1,2,3,4),cache,6).equals(Arrays.asList(4)),"only new page fragments requested");check(Core.missing(Arrays.asList(0,1,2,3),cache,6).isEmpty(),"re-reading does not request cached units");check(Core.missing(Core.window(pages,10),cache,6).equals(Arrays.asList(20,21,22,23,24,25)),"jump uses new location and bounds batch size");String s="";for(int i=0;i<100;i++)s+="Hello. 你好！ 😀 ";s=s.trim();StringBuilder joined=new StringBuilder();boolean bounded=true;for(String p:Core.split(s,260)){joined.append(p);bounded&=p.length()<=260&&!Character.isHighSurrogate(p.charAt(p.length()-1));}check(joined.toString().equals(s)&&bounded,"lossless Unicode-safe segmentation");check(Core.pageAt(pages,5)==2,"position remains anchored after reopening");System.out.println(count+" checks passed.");}}
